// packages/learning/test/pdf-parser.test.ts
//
// Integration tests for the PDF parser (plan §7.2). Uses a small fixture
// PDF generated by reportlab with 2 pages of English text.
//
// Skip in CI by setting SKIP_PDF_PARSER=1 if pdfjs-dist is not available.

import { expect, test, describe } from "bun:test"
import { Effect } from "effect"
import { readFileSync } from "node:fs"
import { join, dirname } from "node:path"
import { fileURLToPath } from "node:url"
import { parsePdf, parse } from "../src/parsers"

const __dirname = dirname(fileURLToPath(import.meta.url))
const FIXTURE_PATH = join(__dirname, "fixtures", "sample.pdf")
const SKIP = process.env.SKIP_PDF_PARSER === "1"

describe.skipIf(SKIP)("PDF parser", () => {
  test("parses a 2-page fixture PDF", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parsePdf(data))
    expect(result.metadata.pages).toBe(2)
    expect(result.pages.length).toBe(2)
  }, 30_000)

  test("extracts text from page 1", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parsePdf(data))
    const page1 = result.pages[0]!
    expect(page1.text).toContain("Chapter 1")
    expect(page1.text).toContain("photosynthesis")
  }, 30_000)

  test("extracts text from page 2", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parsePdf(data))
    const page2 = result.pages[1]!
    expect(page2.text).toContain("Chapter 2")
    expect(page2.text).toContain("Roman Republic")
  }, 30_000)

  test("returns page text with char boxes", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parsePdf(data))
    const page1 = result.pages[0]!
    expect(page1.boxes).toBeDefined()
    expect(page1.boxes!.length).toBeGreaterThan(0)
    // Each box has x, y, w, h, text
    const firstBox = page1.boxes![0]!
    expect(typeof firstBox.x).toBe("number")
    expect(typeof firstBox.y).toBe("number")
    expect(typeof firstBox.text).toBe("string")
  }, 30_000)

  test("textDensity is calculated", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parsePdf(data))
    expect(result.textDensity).toBeGreaterThan(0)
    expect(result.textDensity).toBeLessThanOrEqual(1)
  }, 30_000)

  test("dispatcher routes PDF format correctly", async () => {
    const data = new Uint8Array(readFileSync(FIXTURE_PATH))
    const result = await Effect.runPromise(parse(data, "pdf"))
    expect(result.metadata.pages).toBe(2)
  }, 30_000)
})
